/* @autogenerated */
package net.civeira.phylax.feature.oauth.userinvitation.domain;

import java.time.Instant;

/**
 * A stored invitation, as the invitation flows need it (task 2.2).
 *
 * @param uid invitation identifier
 * @param tenantUid tenant the invitee joins
 * @param email invitee address, the username of the account created on acceptance
 * @param status {@code PENDING}, {@code ACCEPTED}, {@code CANCELLED} or {@code EXPIRED}
 * @param expiresAt when the link stops working
 */
public record InvitationRecord(String uid, String tenantUid, String email, String status,
    Instant expiresAt) {

  public static final String PENDING = "PENDING";

  /**
   * Whether the invitation can still be accepted, cancelled or resent.
   *
   * @param now current instant
   * @return true when pending and not expired
   */
  public boolean open(Instant now) {
    return PENDING.equals(status) && expiresAt != null && expiresAt.isAfter(now);
  }
}

